WITH shipments_by_order AS (SELECT order_id, COUNT(CASE WHEN status = 'DELIVERED' THEN 1 END) AS delivered_count, SUM(CASE WHEN status = 'DELIVERED' THEN cost ELSE 0 END) AS delivered_cost FROM shipments WHERE cost >= 80 GROUP BY order_id) SELECT o.shipping_fee, o.customer_id, sbo.delivered_count, sbo.delivered_cost FROM orders o INNER JOIN shipments_by_order sbo ON o.id = sbo.order_id;
